import type { Config } from "jest";

const config: Config = {
  preset: "ts-jest",
  testEnvironment: "node",
  roots: ["<rootDir>/src"],
  testMatch: ["**/__tests__/**/*.test.ts"],
};

export default config;

export type Frontmatter = Record<string, string>;

export interface PageData {
  path: string;
  frontmatter: Frontmatter;
  html: string;
}

import { promises as fs } from "fs";
import path from "path";
import matter from "gray-matter";
import { marked } from "marked";
import { PageData, Frontmatter } from "./types";

async function walkDir(
  dir: string,
  baseDir: string,
  results: string[]
): Promise<string[]> {
  const entries = await fs.readdir(dir, { withFileTypes: true });
  const sortedEntries = entries
    .filter((e) => e.isFile() && e.name.endsWith(".md"))
    .sort((a, b) => a.name.localeCompare(b.name));

  for (const entry of sortedEntries) {
    results.push(path.relative(baseDir, path.join(dir, entry.name)));
  }

  const subdirs = entries
    .filter((e) => e.isDirectory())
    .sort((a, b) => a.name.localeCompare(b.name));

  for (const subdir of subdirs) {
    await walkDir(path.join(dir, subdir.name), baseDir, results);
  }

  return results;
}

export async function getMarkdownFiles(
  contentDir: string
): Promise<string[]> {
  const absDir = path.resolve(contentDir);
  try {
    await fs.access(absDir);
  } catch {
    throw new Error(`Content directory not found: ${absDir}`);
  }
  const files: string[] = [];
  await walkDir(absDir, absDir, files);
  return files.sort();
}

export async function parseMarkdownFile(
  contentDir: string,
  filePath: string
): Promise<PageData> {
  const absPath = path.join(contentDir, filePath);
  const raw = await fs.readFile(absPath, "utf-8");
  const { data, content } = matter(raw);
  const html = marked.parse(content) as string;

  const frontmatter: Frontmatter = {};
  for (const [key, value] of Object.entries(data)) {
    frontmatter[key] = String(value ?? "");
  }

  return { path: filePath, frontmatter, html };
}

export function generatePageHtml(page: PageData): string {
  let title = page.frontmatter.title || page.path;
  const date = page.frontmatter.date
    ? `<p class="date">${page.frontmatter.date}</p>`
    : "";
  const tags = page.frontmatter.tags
    ? `<p class="tags">Tags: ${page.frontmatter.tags}</p>`
    : "";

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${title}</title>
</head>
<body>
${date}
${tags}
${page.html}
</body>
</html>`;
}

export function generateIndexHtml(pages: PageData[]): string {
  const items = pages
    .map((page) => {
      const href = page.path.replace(/\.md$/, ".html");
      const title = page.frontmatter.title || page.path;
      const date = page.frontmatter.date
        ? `<span class="date">${page.frontmatter.date}</span>`
        : "";
      const tags = page.frontmatter.tags
        ? `<span class="tags">Tags: ${page.frontmatter.tags}</span>`
        : "";
      return `    <li>
      <a href="${href}">${title}</a>
      ${date}
      ${tags}
    </li>`;
    })
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Site Index</title>
</head>
<body>
<h1>Pages</h1>
<ul>
${items}
</ul>
</body>
</html>`;
}

export async function build(options: {
  contentDir: string;
  outputDir: string;
}): Promise<void> {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);

  await fs.mkdir(outputDir, { recursive: true });

  const files = await getMarkdownFiles(contentDir);
  const pages: PageData[] = [];

  for (const file of files) {
    const page = await parseMarkdownFile(contentDir, file);
    pages.push(page);

    const outPath = file.replace(/\.md$/, ".html");
    const fullOutPath = path.join(outputDir, outPath);
    const outDir = path.dirname(fullOutPath);
    await fs.mkdir(outDir, { recursive: true });

    const pageHtml = generatePageHtml(page);
    await fs.writeFile(fullOutPath, pageHtml, "utf-8");
  }

  const indexHtml = generateIndexHtml(pages);
  await fs.writeFile(path.join(outputDir, "index.html"), indexHtml, "utf-8");
}

#!/usr/bin/env node
import { Command } from "commander";
import { build } from "./index";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator");

program
  .command("build")
  .description("Generate the static site")
  .option("--content <dir>", "Content directory", "./content")
  .option("--output <dir>", "Output directory", "./dist")
  .action(async (options: { content: string; output: string }) => {
    try {
      await build({ contentDir: options.content, outputDir: options.output });
      console.log("Build complete");
    } catch (err) {
      console.error("Error:", (err as Error).message);
      process.exit(1);
    }
  });

program.parse();

#!/usr/bin/env node
import { execSync } from "child_process";
import path from "path";
import fs from "fs";
import os from "os";

const testDir = fs.mkdtempSync(
  path.join(os.tmpdir(), "ssg-test-")
);

function cli(...args: string[]): string {
  try {
    const result = execSync(
      `npx ts-node src/cli.ts ${args.join(" ")}`,
      {
        cwd: path.resolve(__dirname, "..", ".."),
        encoding: "utf-8",
        env: { ...process.env, NODE_PATH: "" },
      }
    );
    return result;
  } catch (err: any) {
    return err.stdout + (err.stderr || "");
  }
}

function runBuild(contentDir: string, outputDir: string): string {
  return cli("build", "--content", contentDir, "--output", outputDir);
}

describe("ssg build", () => {
  test("creates output directory", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out1");

    const result = runBuild(contentDir, tmpOut);
    expect(result).toContain("Build complete");
    const stats = fs.statSync(tmpOut);
    expect(stats.isDirectory()).toBe(true);
  });

  test("generates index.html listing all pages", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out2");

    runBuild(contentDir, tmpOut);

    const indexHtml = fs.readFileSync(
      path.join(tmpOut, "index.html"),
      "utf-8"
    );
    expect(indexHtml).toContain("<title>Site Index</title>");
    expect(indexHtml).toContain("Hello World");
    expect(indexHtml).toContain("About");
    expect(indexHtml).toContain("No Date Page");
  });

  test("index.html lists pages in alphabetical order by path", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out3");

    runBuild(contentDir, tmpOut);

    const indexHtml = fs.readFileSync(
      path.join(tmpOut, "index.html"),
      "utf-8"
    );
    const aboutIdx = indexHtml.indexOf("About");
    const helloIdx = indexHtml.indexOf("Hello World");
    const notagsIdx = indexHtml.indexOf("No Date Page");
    expect(aboutIdx).toBeLessThan(helloIdx);
    expect(helloIdx).toBeLessThan(notagsIdx);
  });

  test("generates individual HTML pages", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out4");

    runBuild(contentDir, tmpOut);

    const aboutHtml = fs.readFileSync(
      path.join(tmpOut, "about.html"),
      "utf-8"
    );
    expect(aboutHtml).toContain("<title>About</title>");
    expect(aboutHtml).toContain("<h2>About This Site</h2>");

    const helloHtml = fs.readFileSync(
      path.join(tmpOut, "hello.html"),
      "utf-8"
    );
    expect(helloHtml).toContain("<title>Hello World</title>");
    expect(helloHtml).toContain("<h1>Hello World</h1>");
  });

  test("index.html uses frontmatter as unescaped HTML strings", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out5");

    runBuild(contentDir, tmpOut);

    const indexHtml = fs.readFileSync(
      path.join(tmpOut, "index.html"),
      "utf-8"
    );
    expect(indexHtml).toContain("2024-01-15");
    expect(indexHtml).toContain("Tags: intro, hello");
    expect(indexHtml).toContain("2024-02-20");
    expect(indexHtml).toContain("Tags: meta");
  });

  test("pages with no date/tags omit those sections", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out6");

    runBuild(contentDir, tmpOut);

    const notagsHtml = fs.readFileSync(
      path.join(tmpOut, "notags.html"),
      "utf-8"
    );
    expect(notagsHtml).not.toContain("class=\"date\"");
    expect(notagsHtml).not.toContain("class=\"tags\"");
  });

  test("markdown body is rendered as HTML in page output", () => {
    const contentDir = path.resolve(
      __dirname,
      "..",
      "..",
      "content"
    );
    const tmpOut = path.join(testDir, "out7");

    runBuild(contentDir, tmpOut);

    const aboutHtml = fs.readFileSync(
      path.join(tmpOut, "about.html"),
      "utf-8"
    );
    expect(aboutHtml).toContain("<li>Item one</li>");
    expect(aboutHtml).toContain("<li>Item two</li>");
  });

  test("error on missing content directory", () => {
    const badDir = path.join(testDir, "nonexistent");
    const tmpOut = path.join(testDir, "out8");

    const result = runBuild(badDir, tmpOut);
    expect(result).toContain("Error:");
    expect(result).toContain("not found");
  });

  test("creates subdirectory output for files in subdirectories", () => {
    const contentDir = path.join(testDir, "content-nested");
    const subDir = path.join(contentDir, "posts");
    fs.mkdirSync(subDir, { recursive: true });
    fs.writeFileSync(
      path.join(subDir, "nested-post.md"),
      `---
title: Nested Post
---

# Nested

Content in a subdirectory.
`
    );
    fs.writeFileSync(
      path.join(contentDir, "root-page.md"),
      `---
title: Root Page
---

# Root

Content at root level.
`
    );

    const tmpOut = path.join(testDir, "out9");
    runBuild(contentDir, tmpOut);

    expect(
      fs.existsSync(path.join(tmpOut, "posts", "nested-post.html"))
    ).toBe(true);
    expect(
      fs.existsSync(path.join(tmpOut, "root-page.html"))
    ).toBe(true);

    const nestedHtml = fs.readFileSync(
      path.join(tmpOut, "posts", "nested-post.html"),
      "utf-8"
    );
    expect(nestedHtml).toContain("<title>Nested Post</title>");

    const indexHtml = fs.readFileSync(
      path.join(tmpOut, "index.html"),
      "utf-8"
    );
    expect(indexHtml).toContain("Nested Post");
    expect(indexHtml).toContain("Root Page");
    expect(indexHtml).toContain('href="posts/nested-post.html"');
    expect(indexHtml).toContain('href="root-page.html"');
  });
});

